const c = await api.get("/customers");
const m = await api.get("/mails", { label: "complaint" });
const customers = c.items.map(x => ({id: x.id, name: x.name, status: x.order && x.order.status, eta: x.order && x.order.eta}));
return { customers, complaintMails: m.items.map(x => ({id: x.id, customer_id: x.customer_id, subject: x.subject, label: x.label})), count: m.count };

